Translate the following GNU C++ code to Python 3 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++ code you have to translate:
<original_code>
#include <cstdio>
#include <cstring>
#include <algorithm>
#include <cmath>
using namespace std;
const int MAX_SIZE=1000010;
const long long MODULUS=1000000007;
long long total_p, multiplier, answer=1, visited_flags[MAX_SIZE], cycle_counts[MAX_SIZE];
void traverse(int node, int depth)
{
    if(visited_flags[node]==1)
    {
        cycle_counts[depth]++;
        return;
    }
    visited_flags[node]=1;
    traverse(((long long)node*multiplier)%total_p, depth+1);
}
int main()
{
#ifdef sherco
    freopen("wtf.txt","r",stdin);
    freopen("a.txt","w",stdout);
#endif
    scanf("%lld%lld",&total_p,&multiplier);
    if(multiplier!=0&&multiplier!=1)
    {
        for(int i=1;i<total_p;i++)
            if(visited_flags[i]==0)
                traverse(i,0);
        for(int i=1;i<=total_p;i++)
            for(int j=1;j<=cycle_counts[i];j++)
                answer=((answer*(cycle_counts[i]*i+1)))%MODULUS;
    }
    else if(multiplier==0)
        for(int i=1;i<total_p;i++)
            answer=(answer*total_p)%MODULUS;
    else if(multiplier==1)
        for(int i=1;i<=total_p;i++)
            answer=(answer*total_p)%MODULUS;
    printf("%lld\n",answer);
    return 0;
}
